# Settings of the TARGETGEN DSpark drafter for Grug-67B-A2B-Datakit-SFT-262K-2026.09.21. Sibling of ../dspark_grug-67b-a2b-datakit-sft_datakit-sft-mix_itw (same drafter, recipe and prompts);
# the difference is the supervised text: there it is the dataset's gold replies, here it is the TARGET'S OWN replies to the same conversations (generated by tools/regenerate_token_rows.py).
# Stages (vista/submit_chain.sh): regen (2 gb nodes) -> train job (2 gb nodes: first the merge, then the itw run_2node_ddp.sh with this file's settings).
# Sourced after env.sh (needs PROJECT_ROOT and EXP_DIR). It starts from the itw settings and overrides what differs.
ITW_EXP="$(cd "$EXP_DIR/../dspark_grug-67b-a2b-datakit-sft_datakit-sft-mix_itw" && pwd)"
source "$ITW_EXP/settings.sh"

# ---- regeneration ----
SOURCE_DATA=${SOURCE_DATA:-/scratch/09749/atutej/marin_datakit/dataset_seq32768}   # the Datakit rows (token ids + loss mask) whose conversations are replayed
REGEN_ROWS=${REGEN_ROWS:-270000}          # rows sampled uniformly without replacement from the train split (4.2% of it).
REGEN_SEED=${REGEN_SEED:-0}
REGEN_CONCURRENCY=${REGEN_CONCURRENCY:-512}          # requests in flight per node (= the server's --max-num-seqs)
REGEN_MAX_NEW_TOKENS=${REGEN_MAX_NEW_TOKENS:-32768}  # per assistant turn; the row's 32,768-token window is the real limit (a row reaching it is cut there)
REGEN_MODEL_LEN=$SEQ_LENGTH
# Measured on one gb node (4 GPUs, DP4 x EP4, 512 sequences): 18,984 generated tokens/s steady state, 4,413 generated tokens per row, so 270k rows on 2 nodes = about 8.7 h. No time box: every sampled row is regenerated.
# Forced, never inherited: the itw settings above set WORK_DIR to runs/grug_dspark_full, which holds the ITW run's checkpoints (a train job there would resume from and prune them).
WORK_DIR="${TARGETGEN_WORK_DIR:-$PROJECT_ROOT/runs/grug_dspark_onpolicy}"
# The first regen job (1075248) was started while WORK_DIR still resolved to runs/grug_dspark_full, so its parts are written there. Both the regen and merge stages first copy
# whatever is in REGEN_PARTS_SRC into PARTS_DIR (cp -n: nothing is overwritten), so the targetgen work dir ends up holding all of its own data and a resumed regen skips those rows.
REGEN_PARTS_SRC="${TARGETGEN_PARTS_SRC:-$PROJECT_ROOT/runs/grug_dspark_full/regen_parts}"
PARTS_DIR="$WORK_DIR/regen_parts"
DATA_DIR="$WORK_DIR/data"                # (never inherited from the itw settings: that is the source dataset) the merged targetgen dataset (Arrow + token_freq.pt + the draft-vocabulary maps made from the target's own tokens)
CKPT_DIR="$WORK_DIR/checkpoints"
LOG_DIR="$WORK_DIR/logs"
DRAFT_CONFIG="$ITW_EXP/draft_config.json"

# (the three values below are assigned outright: ${VAR:-default} would keep the itw settings' values, sourced above)
# ---- training on the regenerated rows: 270k rows x about 7.9k tokens = 2.1B tokens = about 18k steps of 120k tokens (about 2.6 h on 2 nodes) ----
TRAIN_DATA_RATIO=0.995   # 0.5% held out for the end-of-run validation (about 1,300 rows)
CKPT_FREQ=0.03                  # a checkpoint every 3% of the epoch (about 540 steps, about 5 min)
MAX_STEPS=""                                  # empty: one epoch over the targetgen data
TRAIN_EXTRA=(--train-data-ratio "$TRAIN_DATA_RATIO")
[[ -z "$MAX_STEPS" ]] || TRAIN_EXTRA+=(--max-steps "$MAX_STEPS")
HF_DESCRIPTION="DSpark drafter (3 layers, FFN 3840) for open-athena/Grug-67B-A2B-Datakit-SFT-262K-2026.09.21, trained TARGETGEN: on the target's own replies to the Datakit SFT conversations (32K context)."
